	// APIs, and each component's Provides/Consumes below, are the contract
	// (request/response) surfaces. Their element shape is not yet finalized,
	// so they are parsed opaquely: preserved for round-tripping to the
	// frontend without asserting a schema the CLI does not yet render.
	APIs []json.RawMessage `json:"apis,omitempty"`
	// Development carries the local-run surface. It appears only on records
	// emitted by the graph-development verb and is nil on deployed
	// topologies. The record's mocks, services, and component-level uses
	// sections are deliberately not modeled: nothing in the CLI renders
	// them, and no consumer round-trips the record — opaque pass-throughs
	// exist (see APIs) only where a consumer renders the data.
	Development *Development `json:"development,omitempty"`
}

// Development is the system's local-run surface: the file directories a
// development topology materializes its connectors as. Only Files is
// modeled — the mocks section is out of scope for every current consumer.
type Development struct {
	Files []DevelopmentFile `json:"files,omitempty"`
}

// DevelopmentFile maps a connector to the local directory its development
// materialization watches. Direction is deliberately absent: it joins from
// the same record's Connectors[].Directions rather than being restated
// here. RootPath is emitted as an absolute path by the host.
type DevelopmentFile struct {
	Connector string `json:"connector"`
	RootPath  string `json:"rootPath"`
}

