package topology

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/integrio-intropy/intropy-cli/internal/command"
)

// GraphTimeout bounds one system's graph task. It is generous because a cold
// project pays for a full build before the verb executes.
const GraphTimeout = 5 * time.Minute

// stderrTailBytes bounds how much of a failing task's output is echoed into
// the error message.
const stderrTailBytes = 2048

// The verbs the CLI delegates to. Each is a named task in the system
// directory's Taskfile that prints exactly one topology record as JSON on
// stdout, nothing else.
const (
	// GraphTask is the deployed topology. Every system must declare it.
	GraphTask = "graph"
	// GraphDevelopmentTask is the development topology — the mocks and
	// file connectors a system wires up for local runs. It is optional:
	// a system with no development definition omits it, and consumers
	// degrade gracefully rather than failing.
	GraphDevelopmentTask = "graph-development"
)

// taskfileNames are the filenames Task looks for, in its search order.
var taskfileNames = []string{"Taskfile.yml", "Taskfile.yaml"}

// ContractError reports a system directory that does not satisfy a task
// contract it is required to, or declares a task whose stdout breaks the
// contract. It is a setup problem, distinct from a task that ran and
// failed, so callers can route the developer to their own Taskfile rather
// than to the tooling.
type ContractError struct {
	SystemDir string
	Problem   string
}

func (e *ContractError) Error() string {
	return fmt.Sprintf("%s: %s\nsee the graph task contract (docs/contracts/graph-task.md) and the sample Taskfiles shipped with the template library", e.SystemDir, e.Problem)
}

// ErrVerbNotDeclared reports that an optional contract verb has no task in
// the system's Taskfile. It is not a failure: callers use errors.Is to
// detect it and degrade gracefully (for example, the dashboard hides the
// development view). A missing required verb is a ContractError instead.
var ErrVerbNotDeclared = errors.New("verb not declared")

// RunGraph executes a system's deployed-topology task and decodes its stdout.
// It is RunVerb for the required GraphTask verb.
func RunGraph(ctx context.Context, runner command.Runner, hostDir string) (*Topology, error) {
	return RunVerb(ctx, runner, hostDir, GraphTask, true)
}

// RunGraphDevelopment executes a system's development-topology task and
// decodes its stdout. When the system declares no graph-development task it
// returns ErrVerbNotDeclared, which callers map to graceful degradation.
func RunGraphDevelopment(ctx context.Context, runner command.Runner, hostDir string) (*Topology, error) {
	return RunVerb(ctx, runner, hostDir, GraphDevelopmentTask, false)
}

// RunVerb executes one contract verb in the system directory that holds
// hostDir, and decodes its stdout as a topology record.
//
// hostDir is the system host's project directory; the contract lives one
// level up, in the system directory that holds the host and its components.
// The Taskfile belongs there because the contract is the system's
// operations surface: verbs like start and stop will orchestrate the host
// and its sibling components, which a Taskfile inside the host project
// cannot naturally address. The host directory's generic name — often just
// "system-host" — is a mechanism detail, not the system's identity.
//
// required decides what a missing task means: a ContractError for a verb
// every system must declare, ErrVerbNotDeclared for an optional one.
//
// The CLI owns the contract, not the process: what the task does to produce
// the record — build flags, codegen, which project executes — is the
// Taskfile's business, and this function must not grow opinions about it.
// --silent keeps Task's own command echo off stdout so the record stays
// the only thing Decode sees.
//
// Callers should say what they are doing before calling: on a cold project
// this can take minutes, and a silent wait that long reads as a hang.
func RunVerb(ctx context.Context, runner command.Runner, hostDir, verb string, required bool) (*Topology, error) {
	systemDir := filepath.Dir(hostDir)
	if err := checkVerbContract(systemDir, verb, required); err != nil {
		return nil, err
	}

	ctx, cancel := context.WithTimeout(ctx, GraphTimeout)
	defer cancel()

	stdout, stderr, err := runner.Run(ctx, systemDir, "task", "--silent", verb)
	if err != nil {
		// The binary itself missing is an environment problem; the runner's
		// NotInstalledError already says how to fix it.
		if errors.Is(err, command.ErrNotInstalled) {
			return nil, err
		}
		// A cancelled context is the caller interrupting; report that rather
		// than blaming the task.
		if errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) {
			return nil, err
		}
		return nil, fmt.Errorf("%s task failed: %v%s", verb, err, tail(stderr))
	}
	t, err := Decode(bytes.NewReader(stdout))
	if err != nil {
		// The stdout tail is the evidence: a decode failure means the task
		// printed something other than the record.
		return nil, fmt.Errorf("%w%s", err, tail(stdout))
	}
	return t, nil
}

// checkVerbContract verifies the system directory can answer one verb before
// paying for a subprocess: the Taskfile must exist and declare a task with
// the verb's name. A stricter YAML parse is deliberately not used — matching
// Task's include and merge semantics would replicate Task itself, and a
// false negative here only costs a subprocess for a file that already
// declared the task.
func checkVerbContract(systemDir, verb string, required bool) error {
	content, err := readTaskfile(systemDir)
	if err != nil {
		return err
	}
	if !declaresTask(content, verb) {
		if !required {
			return fmt.Errorf("%w: %s", ErrVerbNotDeclared, verb)
		}
		return &ContractError{SystemDir: systemDir, Problem: fmt.Sprintf("Taskfile has no %q task", verb)}
	}
	return nil
}

// readTaskfile returns the content of the system directory's Taskfile, or a
// ContractError when none exists.
func readTaskfile(systemDir string) ([]byte, error) {
	for _, name := range taskfileNames {
		b, err := os.ReadFile(filepath.Join(systemDir, name))
		if err == nil {
			return b, nil
		}
		if !errors.Is(err, os.ErrNotExist) {
			return nil, fmt.Errorf("read %s: %w", filepath.Join(systemDir, name), err)
		}
	}
	return nil, &ContractError{SystemDir: systemDir, Problem: "no Taskfile found"}
}

// declaresTask reports whether Taskfile content declares a task with the
// given name. Task names are keys under "tasks:", so a line whose first
// token is the name followed by a colon is a declaration; a reference to
// the name elsewhere is not.
func declaresTask(content []byte, name string) bool {
	for line := range strings.Lines(string(content)) {
		if rest, ok := strings.CutPrefix(strings.TrimLeft(line, " \t"), name+":"); ok && rest != "" {
			return true
		}
	}
	return false
}

// tail formats the last stderrTailBytes of a command stream for inclusion in
// an error message, or nothing when the stream is empty.
func tail(b []byte) string {
	s := strings.TrimSpace(string(b))
	if s == "" {
		return ""
	}
	if len(s) > stderrTailBytes {
		s = "…" + s[len(s)-stderrTailBytes:]
	}
	return ": " + s
}

// Package dashboard serves the local Intropy integration dashboard: a small
// stdlib net/http server that exposes a read-only JSON API over the
// integrations discovered under a workspace root and serves the embedded SPA
// that renders them.
//
// It starts no integration processes and changes nothing. What it does run is
// two things, both on request rather than at startup: each system host's `graph`
// verb, for the topology the flow view draws, and the deploy status command, for
// what the catalog reports each environment is running. The second one refreshes
// the cached GitOps checkout and reads ArgoCD, so it is the only part of this
// package that touches the network — asked for one integration at a time, and
// reused until an explicit refresh.
//
// Deployment facts are never derived here. The command owns every refusal that
// matters — an unset gitopsRepo, a component name matching several, an
// environment nobody has onboarded — and its answers are passed through
// verbatim, so the dashboard cannot claim something the command line would not.
package dashboard

import (
	"context"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"os"
	"time"
)

// Options configures a dashboard server. The zero value is not usable; Root is
// required and Addr/Port select the listen address.
type Options struct {
	// Root is the workspace directory scanned for integrations.
	Root string
	// Addr is the host/interface to bind, e.g. "127.0.0.1". Empty binds all.
	Addr string
	// Port is the TCP port to bind. 0 asks the OS for a free port.
	Port int
	// OpenBrowser opens the dashboard URL in the default browser on start.
	OpenBrowser bool
	// Version is reported by GET /api/health.
	Version string
	// Stdout and Stderr receive program output and diagnostics; both default
	// to the process streams when nil.
	Stdout io.Writer
	Stderr io.Writer
}

// shutdownTimeout bounds how long in-flight requests have to drain on Ctrl+C.
const shutdownTimeout = 5 * time.Second

// Serve starts the dashboard and blocks until ctx is cancelled (e.g. SIGINT)
// or the server fails. On cancellation it shuts down gracefully and returns
// nil; it returns a non-nil error only for a real startup or runtime failure.
func Serve(ctx context.Context, opts Options) error {
	if opts.Stdout == nil {
		opts.Stdout = os.Stdout
	}
	if opts.Stderr == nil {
		opts.Stderr = os.Stderr
	}
	root := opts.Root
	if root == "" {
		root = "."
	}

	handler, err := newHandler(root, opts.Version, providers{
		topology: hostGraphProvider(root),
		deploy:   statusCommandProvider(opts.Version),
	})
	if err != nil {
		return fmt.Errorf("run: %w", err)
	}

	addr := net.JoinHostPort(opts.Addr, fmt.Sprintf("%d", opts.Port))
	ln, err := net.Listen("tcp", addr)
	if err != nil {
		return fmt.Errorf("run: cannot listen on %s: %w", addr, err)
	}

	url := displayURL(opts.Addr, ln.Addr())
	fmt.Fprintf(opts.Stderr, "Intropy dashboard running at %s\n", url)
	fmt.Fprintln(opts.Stderr, "Press Ctrl+C to stop.")

	if opts.OpenBrowser {
		if err := openBrowser(url); err != nil {
			fmt.Fprintf(opts.Stderr, "warning: could not open browser: %v\n", err)
		}
	}

	srv := &http.Server{Handler: handler}
	errCh := make(chan error, 1)
	go func() {
		err := srv.Serve(ln)
		if err != nil && !errors.Is(err, http.ErrServerClosed) {
			errCh <- err
			return
		}
		errCh <- nil
	}()

	select {
	case <-ctx.Done():
		fmt.Fprintln(opts.Stderr, "\nShutting down…")
		shutdownCtx, cancel := context.WithTimeout(context.Background(), shutdownTimeout)
		defer cancel()
		if err := srv.Shutdown(shutdownCtx); err != nil {
			return fmt.Errorf("run: shutdown: %w", err)
		}
		return nil
	case err := <-errCh:
		if err != nil {
			return fmt.Errorf("run: server error: %w", err)
		}
		return nil
	}
}

// displayURL builds a browser-friendly URL. It uses the actual bound port
// (important when Port was 0) and rewrites wildcard bind hosts to localhost.
func displayURL(host string, addr net.Addr) string {
	port := 0
	if tcp, ok := addr.(*net.TCPAddr); ok {
		port = tcp.Port
	}
	if host == "" || host == "0.0.0.0" || host == "::" {
		host = "localhost"
	}
	return fmt.Sprintf("http://%s", net.JoinHostPort(host, fmt.Sprintf("%d", port)))
}


