package dashboard

import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"path/filepath"
	"strings"
	"sync"

	"github.com/integrio-intropy/intropy-cli/internal/command"
	"github.com/integrio-intropy/intropy-cli/internal/template"
	"github.com/integrio-intropy/intropy-cli/internal/topology"
)

// developmentProvider runs one system host's graph-development verb. It is
// per-host — unlike hostGraphProvider's whole-workspace enumeration — so
// reloading one system never re-runs another's verb: each run can cost a
// cold build. Tests replace it.
type developmentProvider func(ctx context.Context, hostDir string) (*topology.Topology, error)

// devStateName identifies which of the four development-record states a
// cached entry holds.
type devStateName string

const (
	// devNotLoaded means the verb has never been run for the system. GET
	// serves this without computing: a cold graph-development can build
	// for minutes, and a synchronous first GET would hang the request
	// that long with no honest UI state. POST is the explicit load.
	devNotLoaded devStateName = "not-loaded"
	// devLoaded means a record was produced and validated.
	devLoaded devStateName = "loaded"
	// devNotDeclared means the system's Taskfile declares no
	// graph-development task. Per the contract this is not an error: the
	// feature is simply absent for that system.
	devNotDeclared devStateName = "not-declared"
	// devError means the verb ran and failed, or its record broke the
	// contract. The command's message is carried verbatim.
	devError devStateName = "error"
)

// developmentReport is the per-system development payload: the cached state
// plus, when loaded, the record itself and any per-connector validation
// failures.
type developmentReport struct {
	// Path is the root-relative system directory identifier, matching the
	// identifier space the rest of the API uses.
	Path string `json:"path"`
	// State is one of not-loaded, loaded, not-declared, error.
	State devStateName `json:"state"`
	// System is the name the record declares, when loaded.
	System string `json:"system,omitempty"`
	// Topology is the development record, when loaded.
	Topology *topology.Topology `json:"topology,omitempty"`
	// Error is the verb's own message, verbatim, when State is error.
	Error string `json:"error,omitempty"`
	// ConnectorErrors names connectors whose declared rootPath failed
	// validation, with the reason. The record still loads: one bad
	// connector does not hide the rest (the contract's per-system isolation
	// rule, applied within the system).
	ConnectorErrors map[string]string `json:"connectorErrors,omitempty"`
}

// developmentSystem is one entry of the system list the Test view's
// selector reads: every scaffolded system host, whether or not it declares
// graph-development — a system with no development verb must still be
// selectable so the view can render its not-declared state.
type developmentSystem struct {
	Path string `json:"path"`
	Name string `json:"name"`
}

// devCacheEntry is one system's cached load result plus the in-flight
// marker that keeps a concurrent GET from waiting on a cold build: the
// mutex guards only the map fields, and a GET during a load serves the
// last cached state immediately.
type devCacheEntry struct {
	report  developmentReport
	loading bool
}

// developmentCache holds per-system load results. The per-key locking is
// deliberate where cachedDeployState's package-wide lock is not: that lock
// exists because the deploy command takes an exclusive lock on a shared
// GitOps checkout, and no such shared resource exists here.
type developmentCache struct {
	mu      sync.Mutex
	entries map[string]*devCacheEntry
}

func newDevelopmentCache() *developmentCache {
	return &developmentCache{entries: map[string]*devCacheEntry{}}
}

// get returns the cached report for path, or the not-loaded state.
func (c *developmentCache) get(path string) developmentReport {
	c.mu.Lock()
	defer c.mu.Unlock()
	if e, ok := c.entries[path]; ok {
		return e.report
	}
	return developmentReport{Path: path, State: devNotLoaded}
}

// beginLoad marks path as loading and reports whether the caller won the
// load. A concurrent POST joins the in-flight load rather than starting a
// second verb run — the same bargain cachedTopologies makes, but per key.
func (c *developmentCache) beginLoad(path string) (won bool) {
	c.mu.Lock()
	defer c.mu.Unlock()
	e, ok := c.entries[path]
	if !ok {
		e = &devCacheEntry{report: developmentReport{Path: path, State: devNotLoaded}}
		c.entries[path] = e
	}
	if e.loading {
		return false
	}
	e.loading = true
	return true
}

// finishLoad stores the result and clears the in-flight marker. waiters
// (a POST that lost beginLoad) receive the same report.
func (c *developmentCache) finishLoad(path string, r developmentReport) {
	c.mu.Lock()
	defer c.mu.Unlock()
	e := c.entries[path]
	e.report = r
	e.loading = false
}

// hostDevelopmentProvider is the default provider: it runs the host's
// graph-development verb via the same topology package deploy init and the
// flow view share.
func hostDevelopmentProvider() developmentProvider {
	return func(ctx context.Context, hostDir string) (*topology.Topology, error) {
		return topology.RunGraphDevelopment(ctx, command.ExecRunner{}, hostDir)
	}
}

// listDevelopmentSystems serves the Test view's system selector: every
// scaffolded system host, in walk order. The scan — not /api/topology — is
// the source, because a system whose graph verb is broken but whose
// graph-development works must stay reachable, and a system with no
// development verb must be selectable to render its not-declared state.
func (s *apiServer) listDevelopmentSystems(w http.ResponseWriter, _ *http.Request) {
	hosts, _ := template.ListSystemHosts(s.root)
	systems := make([]developmentSystem, 0, len(hosts))
	for _, h := range hosts {
		systems = append(systems, developmentSystem{
			Path: s.relPath(filepath.Dir(h.Path)),
			Name: systemName(h),
		})
	}
	writeJSON(w, http.StatusOK, systems)
}

// getDevelopment serves the cached development state for one system. It
// never runs the verb: an unloaded system answers not-loaded, and a system
// mid-load answers its previous state — the Test view's load button (POST)
// is the only thing that computes.
func (s *apiServer) getDevelopment(w http.ResponseWriter, r *http.Request) {
	s.developmentByPath(w, r, false)
}

// loadDevelopment (re)runs one system's graph-development verb and serves
// the fresh state. Concurrent loads for the same system share one run.
func (s *apiServer) loadDevelopment(w http.ResponseWriter, r *http.Request) {
	s.developmentByPath(w, r, true)
}

func (s *apiServer) developmentByPath(w http.ResponseWriter, r *http.Request, load bool) {
	want := strings.Trim(r.PathValue("path"), "/")
	if want == "" {
		want = "."
	}
	host, ok := s.findSystemHost(want)
	if !ok {
		writeError(w, http.StatusNotFound, "system not found: "+want)
		return
	}
	if !load {
		writeJSON(w, http.StatusOK, s.devCache.get(want))
		return
	}
	writeJSON(w, http.StatusOK, s.loadDevelopmentState(r.Context(), want, host))
}

// loadDevelopmentState runs the verb for one system and caches the result,
// sharing one run between concurrent callers. The provider call happens
// outside the cache lock so a cold build blocks neither other systems nor
// same-system GETs.
func (s *apiServer) loadDevelopmentState(ctx context.Context, path string, host template.ScaffoldEntry) developmentReport {
	if !s.devCache.beginLoad(path) {
		// Another request is already running the verb for this system;
		// serve whatever state it replaces when it lands. Joining properly
		// (waiting) would reintroduce the multi-minute request the
		// not-loaded state exists to avoid, so the loser simply re-reads.
		return s.devCache.get(path)
	}

	report := developmentReport{Path: path, State: devLoaded}
	t, err := s.dev(ctx, host.Path)
	switch {
	case errors.Is(err, topology.ErrVerbNotDeclared):
		report.State = devNotDeclared
	case err != nil:
		report.State = devError
		report.Error = err.Error()
	default:
		report.System = t.System
		report.Topology = t
		report.ConnectorErrors = s.validateRootPaths(filepath.Dir(host.Path), t)
		if len(report.ConnectorErrors) == 0 {
			report.ConnectorErrors = nil
		}
	}
	s.devCache.finishLoad(path, report)
	return report
}

// validateRootPaths checks every declared development file directory lies
// within the system host's own tree. The record is produced by a Taskfile
// verb in repo code — templates, dependencies, cloned repositories — and
// the dashboard's file endpoints then read and write into whatever
// directories it declares. Confining declarations to the system tree keeps
// a crafted or buggy record from pointing those endpoints anywhere else.
func (s *apiServer) validateRootPaths(systemDir string, t *topology.Topology) map[string]string {
	if t.Development == nil {
		return nil
	}
	root, err := canonicalDir(systemDir)
	if err != nil {
		return map[string]string{"": fmt.Sprintf("resolve system directory: %v", err)}
	}
	var errs map[string]string
	for _, f := range t.Development.Files {
		p, err := canonicalDir(f.RootPath)
		if err != nil {
			errs = putConnectorError(errs, f.Connector, fmt.Sprintf("resolve rootPath: %v", err))
			continue
		}
		if !withinDir(root, p) {
			errs = putConnectorError(errs, f.Connector,
				fmt.Sprintf("rootPath %s lies outside the system directory %s", f.RootPath, systemDir))
		}
	}
	return errs
}

// canonicalDir resolves p to an absolute, symlink-evaluated path. The
// directory need not exist: a watched dir appears when the system first
// runs, so resolution falls back to the lexical absolute path when
// EvalSymlinks cannot stat it (a missing leaf cannot contain a symlink
// escape its existing parents don't already).
func canonicalDir(p string) (string, error) {
	abs, err := filepath.Abs(p)
	if err != nil {
		return "", err
	}
	if resolved, err := filepath.EvalSymlinks(abs); err == nil {
		return resolved, nil
	}
	return filepath.Clean(abs), nil
}

// withinDir reports whether p equals root or lies beneath it, using
// filepath.Rel so the check is element-aware: a string prefix match would
// accept a sibling like order-flow-evil under root order-flow.
func withinDir(root, p string) bool {
	rel, err := filepath.Rel(root, p)
	if err != nil {
		return false
	}
	return rel == "." || (rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator)) && !filepath.IsAbs(rel))
}

func putConnectorError(errs map[string]string, connector, msg string) map[string]string {
	if errs == nil {
		errs = map[string]string{}
	}
	errs[connector] = msg
	return errs
}

// findSystemHost resolves a root-relative system path identifier to its
// scaffolded host, mirroring byPath's discipline: the identifier is matched
// against the scanned hosts, never trusted as a path.
func (s *apiServer) findSystemHost(want string) (template.ScaffoldEntry, bool) {
	hosts, _ := template.ListSystemHosts(s.root)
	for _, h := range hosts {
		if s.relPath(filepath.Dir(h.Path)) == want {
			return h, true
		}
	}
	return template.ScaffoldEntry{}, false
}

// connectorRootPath resolves one connector's declared watched directory
// from the cached development record, refusing when the system is not
// loaded, the connector is undeclared, or its rootPath failed validation.
// It is the shared lookup the library, inject, and outputs endpoints all
// authorize against before touching the filesystem.
func (s *apiServer) connectorRootPath(systemPath, connector string) (string, error) {
	report := s.devCache.get(systemPath)
	if report.State != devLoaded || report.Topology == nil || report.Topology.Development == nil {
		return "", fmt.Errorf("development topology not loaded for system %s", systemPath)
	}
	if msg, bad := report.ConnectorErrors[connector]; bad {
		return "", fmt.Errorf("connector %s: %s", connector, msg)
	}
	for _, f := range report.Topology.Development.Files {
		if f.Connector == connector {
			return f.RootPath, nil
		}
	}
	return "", fmt.Errorf("system %s declares no development files for connector %s", systemPath, connector)
}

// connectorDirections joins a connector name against the loaded record's
// connectors[] to group the Test view's panes. Direction lives on the
// record's Connector entries, not on development.files[], so this is the
// one place the join happens.
func (s *apiServer) connectorDirections(systemPath, connector string) []string {
	report := s.devCache.get(systemPath)
	if report.Topology == nil {
		return nil
	}
	for _, c := range report.Topology.Connectors {
		if c.Name == connector {
			return c.Directions
		}
	}
	return nil
}

// libraryDir derives a connector's staging library from its declared
// watched directory: the library is the sibling named library/<connector>
// under the watched dir's parent. The convention keeps authored payloads
// (committed, curated) apart from runtime state (consumed, gitignored)
// with one declared path.
func libraryDir(rootPath, connector string) string {
	return filepath.Join(filepath.Dir(rootPath), "library", connector)
}

