package dashboard

import (
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"path/filepath"
	"strings"
	"sync/atomic"
	"testing"
	"time"

	"github.com/integrio-intropy/intropy-cli/internal/topology"
)

// testHandlerWithDev is the development-endpoint counterpart of
// testHandlerWithTopo: a handler whose development provider is the stub.
func testHandlerWithDev(t *testing.T, root string, dev developmentProvider) http.Handler {
	t.Helper()
	return testHandlerWith(t, root, providers{topology: emptyTopo, deploy: emptyDeploy, development: dev})
}

// devRecord builds a development topology whose file connectors' rootPaths
// live under systemDir, the only shape validateRootPaths accepts.
func devRecord(system, systemDir string, connectors ...string) *topology.Topology {
	t := &topology.Topology{
		APIVersion:  topology.APIVersion,
		System:      system,
		Development: &topology.Development{},
	}
	for _, c := range connectors {
		t.Development.Files = append(t.Development.Files, topology.DevelopmentFile{
			Connector: c,
			RootPath:  filepath.Join(systemDir, "test", c),
		})
		t.Connectors = append(t.Connectors, topology.Connector{
			Name:       c,
			Directions: []string{"in"},
		})
	}
	return t
}

// The system list backs the Test view's selector from the workspace scan,
// not from any topology fetch: every scaffolded host appears, in walk
// order, with its declared name.
func TestDevelopmentSystemsListed(t *testing.T) {
	tmp := t.TempDir()
	t.Chdir(tmp)
	writeSystemHost(t, filepath.Join(tmp, "order-flow", "system-host"), "order-flow")
	writeSystemHost(t, filepath.Join(tmp, "billing", "system-host"), "billing")

	rec := get(t, testHandler(t, "."), "/api/development")
	var systems []developmentSystem
	if err := json.Unmarshal(rec.Body.Bytes(), &systems); err != nil {
		t.Fatalf("body not JSON: %v\n%s", err, rec.Body.String())
	}
	if len(systems) != 2 {
		t.Fatalf("systems = %d, want 2", len(systems))
	}
	if systems[0].Path != "billing" || systems[0].Name != "billing" ||
		systems[1].Path != "order-flow" || systems[1].Name != "order-flow" {
		t.Errorf("systems = %+v", systems)
	}
}

func TestDevelopmentSystemsEmptyIsArray(t *testing.T) {
	t.Chdir(t.TempDir())
	rec := get(t, testHandler(t, "."), "/api/development")
	if got := strings.TrimSpace(rec.Body.String()); got != "[]" {
		t.Errorf("body = %q, want []", got)
	}
}

// GET never computes: an unloaded system answers not-loaded and the
// provider is not called. POST is the explicit load; after it, GET serves
// the cache.
func TestDevelopmentGetNeverComputes(t *testing.T) {
	tmp := t.TempDir()
	t.Chdir(tmp)
	writeSystemHost(t, filepath.Join(tmp, "order-flow", "system-host"), "order-flow")

	var calls atomic.Int32
	dev := func(context.Context, string) (*topology.Topology, error) {
		calls.Add(1)
		return devRecord("order-flow", filepath.Join(tmp, "order-flow"), "src"), nil
	}
	h := testHandlerWithDev(t, ".", dev)

	rec := get(t, h, "/api/development/order-flow")
	var report developmentReport
	if err := json.Unmarshal(rec.Body.Bytes(), &report); err != nil {
		t.Fatalf("body not JSON: %v\n%s", err, rec.Body.String())
	}
	if report.State != devNotLoaded {
		t.Errorf("state = %q, want not-loaded", report.State)
	}
	if calls.Load() != 0 {
		t.Errorf("provider calls after GET = %d, want 0", calls.Load())
	}

	rec = post(t, h, "/api/development/order-flow")
	if err := json.Unmarshal(rec.Body.Bytes(), &report); err != nil {
		t.Fatalf("POST body not JSON: %v\n%s", err, rec.Body.String())
	}
	if report.State != devLoaded || report.System != "order-flow" {
		t.Errorf("after POST: state = %q, system = %q, want loaded/order-flow", report.State, report.System)
	}
	if report.Topology == nil || len(report.Topology.Development.Files) != 1 {
		t.Fatalf("topology files = %+v", report.Topology)
	}
	if calls.Load() != 1 {
		t.Errorf("provider calls after POST = %d, want 1", calls.Load())
	}

	rec = get(t, h, "/api/development/order-flow")
	if err := json.Unmarshal(rec.Body.Bytes(), &report); err != nil {
		t.Fatalf("GET body not JSON: %v", err)
	}
	if report.State != devLoaded || calls.Load() != 1 {
		t.Errorf("cached GET: state = %q, calls = %d, want loaded/1", report.State, calls.Load())
	}

	post(t, h, "/api/development/order-flow")
	if calls.Load() != 2 {
		t.Errorf("provider calls after second POST = %d, want 2", calls.Load())
	}
}

// A system whose Taskfile declares no graph-development verb reports
// not-declared — the feature is absent, not broken (the contract's
// optional-verb rule). Covers AE3.
func TestDevelopmentNotDeclared(t *testing.T) {
	tmp := t.TempDir()
	t.Chdir(tmp)
	writeSystemHost(t, filepath.Join(tmp, "order-flow", "system-host"), "order-flow")

	dev := func(context.Context, string) (*topology.Topology, error) {
		return nil, fmt.Errorf("%w: graph-development", topology.ErrVerbNotDeclared)
	}
	h := testHandlerWithDev(t, ".", dev)

	rec := post(t, h, "/api/development/order-flow")
	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d, want 200", rec.Code)
	}
	var report developmentReport
	if err := json.Unmarshal(rec.Body.Bytes(), &report); err != nil {
		t.Fatalf("body not JSON: %v", err)
	}
	if report.State != devNotDeclared || report.Error != "" {
		t.Errorf("report = %+v, want not-declared without error", report)
	}
}

// A verb that runs and fails reports the command's message verbatim; the
// failure is cached and recomputed on the next POST.
func TestDevelopmentErrorVerbatim(t *testing.T) {
	tmp := t.TempDir()
	t.Chdir(tmp)
	writeSystemHost(t, filepath.Join(tmp, "order-flow", "system-host"), "order-flow")

	dev := func(context.Context, string) (*topology.Topology, error) {
		return nil, fmt.Errorf("graph-development task failed: exit status 1: build broke")
	}
	h := testHandlerWithDev(t, ".", dev)

	rec := post(t, h, "/api/development/order-flow")
	var report developmentReport
	if err := json.Unmarshal(rec.Body.Bytes(), &report); err != nil {
		t.Fatalf("body not JSON: %v", err)
	}
	if report.State != devError ||
		report.Error != "graph-development task failed: exit status 1: build broke" {
		t.Errorf("report = %+v", report)
	}
}

// A record whose connector rootPath resolves outside the system directory
// loads with a per-connector error entry — the rest of the record caches
// normally, and the offending connector's file endpoints refuse.
func TestDevelopmentRootPathOutsideSystemRejected(t *testing.T) {
	tmp := t.TempDir()
	t.Chdir(tmp)
	writeSystemHost(t, filepath.Join(tmp, "order-flow", "system-host"), "order-flow")

	outside := filepath.Join(tmp, "elsewhere", "watched")
	rec := devRecord("order-flow", filepath.Join(tmp, "order-flow"), "src")
	rec.Development.Files = append(rec.Development.Files, topology.DevelopmentFile{
		Connector: "evil",
		RootPath:  outside,
	})
	dev := func(context.Context, string) (*topology.Topology, error) { return rec, nil }
	h := testHandlerWithDev(t, ".", dev)

	resp := post(t, h, "/api/development/order-flow")
	var report developmentReport
	if err := json.Unmarshal(resp.Body.Bytes(), &report); err != nil {
		t.Fatalf("body not JSON: %v", err)
	}
	if report.State != devLoaded {
		t.Fatalf("state = %q, want loaded (record caches despite the bad connector)", report.State)
	}
	msg, bad := report.ConnectorErrors["evil"]
	if !bad || !strings.Contains(msg, "outside the system directory") {
		t.Errorf("connectorErrors = %+v, want an outside-tree entry for evil", report.ConnectorErrors)
	}
	if _, ok := report.ConnectorErrors["src"]; ok {
		t.Errorf("connectorErrors names the valid connector: %+v", report.ConnectorErrors)
	}
}

// withinDir is element-aware: a sibling whose name shares a prefix with
// the system directory is not inside it.
func TestWithinDirSiblingPrefixRejected(t *testing.T) {
	root := filepath.Join(t.TempDir(), "order-flow")
	for p, want := range map[string]bool{
		root:                                  true,
		filepath.Join(root, "test", "src"):    true,
		root + "-evil":                        false,
		filepath.Join(root, "..", "sibling"):  false,
		string(filepath.Separator) + "elsewhere": false,
	} {
		if got := withinDir(root, p); got != want {
			t.Errorf("withinDir(%q, %q) = %v, want %v", root, p, got, want)
		}
	}
}

// Loading one system neither re-runs another's verb nor blocks its
// cache-hit GET, and a same-system GET during the load answers the
// previous state without waiting on the build.
func TestDevelopmentLoadsAreIsolated(t *testing.T) {
	tmp := t.TempDir()
	t.Chdir(tmp)
	writeSystemHost(t, filepath.Join(tmp, "slow", "system-host"), "slow")
	writeSystemHost(t, filepath.Join(tmp, "fast", "system-host"), "fast")

	release := make(chan struct{})
	var slowCalls, fastCalls atomic.Int32
	dev := func(_ context.Context, hostDir string) (*topology.Topology, error) {
		systemDir := filepath.Dir(hostDir)
		switch filepath.Base(systemDir) {
		case "slow":
			slowCalls.Add(1)
			<-release
			return devRecord("slow", systemDir, "src"), nil
		default:
			fastCalls.Add(1)
			return devRecord("fast", systemDir, "src"), nil
		}
	}
	h := testHandlerWithDev(t, ".", dev)

	slowDone := make(chan struct{})
	go func() {
		post(t, h, "/api/development/slow")
		close(slowDone)
	}()
	// Wait until the slow load is actually inside the provider.
	deadline := time.Now().Add(2 * time.Second)
	for slowCalls.Load() == 0 && time.Now().Before(deadline) {
		time.Sleep(time.Millisecond)
	}
	if slowCalls.Load() == 0 {
		t.Fatal("slow load never reached the provider")
	}

	// A same-system GET during the load answers not-loaded immediately.
	done := make(chan *httptest.ResponseRecorder, 1)
	go func() { done <- get(t, h, "/api/development/slow") }()
	select {
	case rec := <-done:
		var report developmentReport
		if err := json.Unmarshal(rec.Body.Bytes(), &report); err != nil {
			t.Fatalf("body not JSON: %v", err)
		}
		if report.State != devNotLoaded {
			t.Errorf("state during load = %q, want not-loaded", report.State)
		}
	case <-time.After(2 * time.Second):
		t.Fatal("GET blocked on the in-flight load")
	}

	close(release)
	<-slowDone
	if fastCalls.Load() != 0 {
		t.Errorf("fast provider calls = %d, want 0 (loading slow must not run fast)", fastCalls.Load())
	}
}

// A path that matches no scanned system host 404s rather than being
// treated as a directory.
func TestDevelopmentUnknownSystem404(t *testing.T) {
	t.Chdir(t.TempDir())
	h := testHandler(t, ".")
	if rec := get(t, h, "/api/development/nope"); rec.Code != http.StatusNotFound {
		t.Errorf("GET status = %d, want 404", rec.Code)
	}
	if rec := post(t, h, "/api/development/nope"); rec.Code != http.StatusNotFound {
		t.Errorf("POST status = %d, want 404", rec.Code)
	}
}

