// canonicalDir resolves p to an absolute, symlink-evaluated path. The
// directory need not exist — a watched dir appears when the system first
// runs — so resolution walks up to the longest existing ancestor,
// evaluates that, and rejoins the missing tail: a missing leaf cannot
// contain a symlink its resolved ancestors don't already. Resolving only
// when the whole path exists would compare a symlink-resolved system dir
// against a lexical rootPath (on macOS /var is a symlink to /private/var)
// and reject every declaration.
func canonicalDir(p string) (string, error) {
	abs, err := filepath.Abs(p)
	if err != nil {
		return "", err
	}
	tail := []string{}
	dir := abs
	for {
		if resolved, err := filepath.EvalSymlinks(dir); err == nil {
			for i := len(tail) - 1; i >= 0; i-- {
				resolved = filepath.Join(resolved, tail[i])
			}
			return resolved, nil
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return filepath.Clean(abs), nil
		}
		tail = append(tail, filepath.Base(dir))
		dir = parent
	}
}

