package dashboard

import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"
	"unicode/utf8"
)

// maxLibraryBytes caps a library write. It is much larger than maxDocBytes
// — that cap was sized for README/AGENTS.md enrichment docs, and test
// payloads (message batches, fixtures) plausibly exceed it — while still
// small enough that buffering the whole body before writing is free.
// Enforcement goes through http.MaxBytesReader so a chunked client cannot
// stream past the cap into memory.
const maxLibraryBytes = 1 << 20

// libraryEntry is one file in a connector's staging library.
type libraryEntry struct {
	Name    string    `json:"name"`
	Size    int64     `json:"size"`
	ModTime time.Time `json:"modTime"`
}

// libraryFile is one library file's content plus the metadata the editor
// needs to be honest about what it is showing. Truncated marks a read cut
// at maxDocBytes — the editor disables save, because writing a truncated
// buffer back would silently destroy content past the cap. Binary marks
// undecodable-as-UTF-8 content (NUL bytes or invalid encoding); the check
// runs here, next to the cap, so a truncated binary read cannot be
// misclassified as text. Schema is the connector's contract schema when it
// resolves unambiguously — a read-only reference, never a validator.
type libraryFile struct {
	Name      string          `json:"name"`
	Content   string          `json:"content"`
	Truncated bool            `json:"truncated,omitempty"`
	Binary    bool            `json:"binary,omitempty"`
	Schema    json.RawMessage `json:"schema,omitempty"`
}

// handleLibrary routes every library request: the wildcard carries the
// system path plus an optional file name, split against the scanned system
// hosts (the byPath discipline — URL segments are never trusted as paths).
func (s *apiServer) handleLibrary(w http.ResponseWriter, r *http.Request) {
	connector := r.PathValue("connector")
	systemPath, fileName, ok := s.splitSystemWildcard(w, r.PathValue("path"))
	if !ok {
		return
	}

	switch {
	case fileName == "" && r.Method == http.MethodGet:
		s.listLibrary(w, systemPath, connector)
	case fileName == "":
		writeError(w, http.StatusMethodNotAllowed, "method not allowed")
	case r.Method == http.MethodGet:
		s.readLibraryFile(w, systemPath, connector, fileName)
	case r.Method == http.MethodPut:
		s.writeLibraryFile(w, r, systemPath, connector, fileName)
	case r.Method == http.MethodDelete:
		s.deleteLibraryFile(w, systemPath, connector, fileName)
	default:
		writeError(w, http.StatusMethodNotAllowed, "method not allowed")
	}
}

// splitSystemWildcard splits a wildcard of the form <system-path>[/<file>]
// by matching the longest scanned system path. A prefix that matches no
// system, or one that matches ambiguously, is a 404/400 — never a guess.
func (s *apiServer) splitSystemWildcard(w http.ResponseWriter, wildcard string) (systemPath, fileName string, ok bool) {
	wildcard = strings.Trim(wildcard, "/")
	if wildcard == "" {
		writeError(w, http.StatusNotFound, "system not found")
		return "", "", false
	}
	best := ""
	bestLen := 0
	hosts, _ := s.scanHosts()
	for _, p := range hosts {
		if wildcard == p || strings.HasPrefix(wildcard, p+"/") {
			if len(p) > bestLen {
				best, bestLen = p, len(p)
			}
		}
	}
	if best == "" {
		writeError(w, http.StatusNotFound, "system not found: "+wildcard)
		return "", "", false
	}
	return best, strings.TrimPrefix(wildcard[len(best):], "/"), true
}

// scanHosts returns the root-relative paths of every scaffolded system
// host — the identifier space the development wildcard resolves against.
func (s *apiServer) scanHosts() ([]string, error) {
	hosts, warnings := s.listHostPaths()
	return hosts, warnings
}

// resolveLibraryFile authorizes one library file operation: the system must
// be loaded, the connector declared and valid, and the file name — joined
// onto the library dir and symlink-resolved — must stay inside it. The
// containment check is element-aware (filepath.Rel, not strings.HasPrefix)
// and follows symlinks, because a lexical check passes both a sibling
// prefix (orders-evil/ under orders/) and a planted symlink pointing out.
func (s *apiServer) resolveLibraryFile(systemPath, connector, name string) (dir, file string, err error) {
	rootPath, err := s.connectorRootPath(systemPath, connector)
	if err != nil {
		return "", "", err
	}
	dir = libraryDir(rootPath, connector)
	base, err := canonicalDir(dir)
	if err != nil {
		return "", "", fmt.Errorf("resolve library directory: %v", err)
	}
	candidate := filepath.Join(base, filepath.FromSlash(name))
	resolved, err := canonicalDir(candidate)
	if err != nil {
		return "", "", fmt.Errorf("resolve %s: %v", name, err)
	}
	if !withinDir(base, resolved) || resolved == base {
		return "", "", fmt.Errorf("file %s escapes the library directory", name)
	}
	return base, resolved, nil
}

// listLibrary serves one connector's staging library, or an empty array
// when the library has not been created yet — never null, never an error.
func (s *apiServer) listLibrary(w http.ResponseWriter, systemPath, connector string) {
	rootPath, err := s.connectorRootPath(systemPath, connector)
	if err != nil {
		writeError(w, http.StatusNotFound, err.Error())
		return
	}
	dir := libraryDir(rootPath, connector)
	entries := []libraryEntry{}
	files, err := libraryFiles(dir)
	if err == nil {
		entries = files
	}
	writeJSON(w, http.StatusOK, entries)
}

// libraryFiles lists the regular files directly under dir. A missing dir
// is an empty library, not a failure (R6 posture: the library appears on
// the first save).
func libraryFiles(dir string) ([]libraryEntry, error) {
	ents, err := os.ReadDir(dir)
	if err != nil {
		return nil, err
	}
	var out []libraryEntry
	for _, ent := range ents {
		info, err := ent.Info()
		if err != nil || !info.Mode().IsRegular() {
			continue
		}
		out = append(out, libraryEntry{Name: ent.Name(), Size: info.Size(), ModTime: info.ModTime()})
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out, nil
}

// readLibraryFile serves one file's (possibly capped) content with its
// truncated/binary flags and the connector's contract schema when it
// resolves to exactly one.
func (s *apiServer) readLibraryFile(w http.ResponseWriter, systemPath, connector, name string) {
	_, file, err := s.resolveLibraryFile(systemPath, connector, name)
	if err != nil {
		writeError(w, http.StatusNotFound, err.Error())
		return
	}
	data, err := os.ReadFile(file)
	if err != nil {
		writeError(w, http.StatusNotFound, fmt.Sprintf("read %s: %v", name, err))
		return
	}
	out := libraryFile{Name: name, Schema: s.connectorSchema(systemPath, connector)}
	out.Content, out.Truncated, out.Binary = cappedText(data)
	writeJSON(w, http.StatusOK, out)
}

// cappedText converts file bytes for the editor: capped at maxDocBytes
// with the truncation flagged, and classified binary when the (possibly
// capped) content is not valid UTF-8 text.
func cappedText(data []byte) (content string, truncated, binary bool) {
	truncated = len(data) > maxDocBytes
	if truncated {
		data = data[:maxDocBytes]
	}
	if !utf8.Valid(data) || strings.IndexByte(string(data), 0) >= 0 {
		binary = true
	}
	return string(data), truncated, binary
}

// writeLibraryFile creates or replaces one library file. The body is
// capped by MaxBytesReader and buffered fully before writing, so an
// over-cap write leaves nothing partial behind. The library directory is
// created on first save — the staging convention exists from the moment
// someone authors a payload.
func (s *apiServer) writeLibraryFile(w http.ResponseWriter, r *http.Request, systemPath, connector, name string) {
	dir, file, err := s.resolveLibraryFile(systemPath, connector, name)
	if err != nil {
		writeError(w, http.StatusNotFound, err.Error())
		return
	}
	r.Body = http.MaxBytesReader(w, r.Body, maxLibraryBytes)
	data, err := io.ReadAll(r.Body)
	if err != nil {
		writeError(w, http.StatusRequestEntityTooLarge,
			fmt.Sprintf("read %s: payload exceeds the %d MiB library cap", name, maxLibraryBytes>>20))
		return
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		writeError(w, http.StatusInternalServerError, fmt.Sprintf("create library directory: %v", err))
		return
	}
	if err := os.WriteFile(file, data, 0o644); err != nil {
		writeError(w, http.StatusInternalServerError, fmt.Sprintf("write %s: %v", name, err))
		return
	}
	writeJSON(w, http.StatusOK, libraryEntry{Name: name, Size: int64(len(data)), ModTime: time.Now()})
}

// deleteLibraryFile removes one library file. The file must exist —
// deleting something that is not there is a mistake worth naming, not a
// no-op to absorb.
func (s *apiServer) deleteLibraryFile(w http.ResponseWriter, systemPath, connector, name string) {
	_, file, err := s.resolveLibraryFile(systemPath, connector, name)
	if err != nil {
		writeError(w, http.StatusNotFound, err.Error())
		return
	}
	if err := os.Remove(file); err != nil {
		writeError(w, http.StatusNotFound, fmt.Sprintf("delete %s: %v", name, err))
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

// handleInject copies one library file into its connector's watched
// directory. The copy is temp-file-then-rename in the destination so the
// running system's own file watcher never sees a partial write; an
// existing symlink at the destination is replaced, not followed. The
// watched dir must already exist — its absence means the system has not
// run yet, and creating runtime directories on the system's behalf is not
// this package's job.
func (s *apiServer) handleInject(w http.ResponseWriter, r *http.Request) {
	connector := r.PathValue("connector")
	systemPath, fileName, ok := s.splitSystemWildcard(w, r.PathValue("path"))
	if !ok {
		return
	}
	if fileName == "" {
		writeError(w, http.StatusBadRequest, "inject names a library file")
		return
	}

	_, src, err := s.resolveLibraryFile(systemPath, connector, fileName)
	if err != nil {
		writeError(w, http.StatusNotFound, err.Error())
		return
	}
	rootPath, err := s.connectorRootPath(systemPath, connector)
	if err != nil {
		writeError(w, http.StatusNotFound, err.Error())
		return
	}
	watched, err := canonicalDir(rootPath)
	if err != nil {
		writeError(w, http.StatusInternalServerError, fmt.Sprintf("resolve watched directory: %v", err))
		return
	}
	info, err := os.Stat(watched)
	if err != nil || !info.IsDir() {
		writeError(w, http.StatusConflict, fmt.Sprintf(
			"watched directory %s does not exist\nstart the system once so its file connector creates it, then inject again",
			rootPath))
		return
	}
	dest := filepath.Join(watched, filepath.Base(src))
	if !withinDir(watched, dest) {
		writeError(w, http.StatusBadRequest, "file name escapes the watched directory")
		return
	}
	if err := copyFileAtomic(src, dest); err != nil {
		writeError(w, http.StatusInternalServerError, fmt.Sprintf("inject %s: %v", fileName, err))
		return
	}
	writeJSON(w, http.StatusOK, map[string]string{
		"injected":    fileName,
		"destination": dest,
	})
}

// copyFileAtomic copies src onto dest via a temp file in the destination
// directory followed by a rename, so a concurrent reader (the running
// system) sees either the old file or the new one, never a mixture.
func copyFileAtomic(src, dest string) error {
	data, err := os.ReadFile(src)
	if err != nil {
		return err
	}
	tmp, err := os.CreateTemp(filepath.Dir(dest), ".inject-*")
	if err != nil {
		return err
	}
	tmpName := tmp.Name()
	defer os.Remove(tmpName)
	if _, err := tmp.Write(data); err != nil {
		tmp.Close()
		return err
	}
	if err := tmp.Close(); err != nil {
		return err
	}
	return os.Rename(tmpName, dest)
}

// connectorSchema resolves a connector's contract schema for the editor's
// reference panel. The join is multi-hop — connector → using component(s)
// → their publishes/subscribes → topic(s) → contract → contracts[] — and
// only a unique match is returned: zero or several candidates means the
// panel stays empty rather than guessing.
func (s *apiServer) connectorSchema(systemPath, connector string) json.RawMessage {
	report := s.devCache.get(systemPath)
	t := report.Topology
	if t == nil {
		return nil
	}
	users := map[string]bool{}
	for _, c := range t.Connectors {
		if c.Name != connector {
			continue
		}
		for _, u := range c.UsedBy {
			users[u] = true
		}
	}
	if len(users) == 0 {
		return nil
	}
	contracts := map[string]bool{}
	for _, comp := range t.Components {
		if !users[comp.Name] {
			continue
		}
		for _, p := range comp.Publishes {
			for _, tp := range t.Topics {
				if tp.PubSub == p.PubSub && tp.Topic == p.Topic && tp.Contract != "" {
					contracts[tp.Contract] = true
				}
			}
		}
		for _, sub := range comp.Subscribes {
			for _, tp := range t.Topics {
				if tp.PubSub == sub.PubSub && tp.Topic == sub.Topic && tp.Contract != "" {
					contracts[tp.Contract] = true
				}
			}
		}
	}
	if len(contracts) != 1 {
		return nil
	}
	var want string
	for name := range contracts {
		want = name
	}
	for _, c := range t.Contracts {
		if c.Name == want && len(c.Schema) > 0 {
			return c.Schema
		}
	}
	return nil
}

