package dashboard

import (
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/integrio-intropy/intropy-cli/internal/topology"
)

// libraryFixture lays out one loaded system — order-flow with connectors
// src (in) and dst (out) — and returns the handler plus the paths the
// tests operate on. The development provider serves the record directly;
// these tests exercise the file endpoints, not the load.
type libraryFixture struct {
	handler   http.Handler
	systemDir string
	library   string
	watched   string
}

func newLibraryFixture(t *testing.T) libraryFixture {
	t.Helper()
	tmp := t.TempDir()
	t.Chdir(tmp)
	systemDir := filepath.Join(tmp, "order-flow")
	writeSystemHost(t, filepath.Join(systemDir, "system-host"), "order-flow")

	record := devRecord("order-flow", systemDir, "src", "dst")
	// dst publishes a contracted topic through its component, so the schema
	// join has exactly one match.
	record.Components = []topology.Component{
		{Name: "loader", Kind: "loader",
			Subscribes: []topology.TopicRef{{PubSub: "pubsub", Topic: "order"}},
			Connectors: []topology.ConnectorUse{{Connector: "dst", Direction: "out"}}},
	}
	record.Topics = []topology.Topic{
		{PubSub: "pubsub", Topic: "order", Contract: "Contracts.Order",
			Subscribers: []string{"loader"}},
	}
	record.Connectors[1].UsedBy = []string{"loader"}
	record.Contracts = []topology.Contract{
		{Name: "Contracts.Order", Schema: json.RawMessage(`{"type":"object"}`)},
	}

	f := libraryFixture{
		systemDir: systemDir,
		library:   filepath.Join(systemDir, "test", "library"),
		watched:   filepath.Join(systemDir, "test"),
	}
	dev := func(context.Context, string) (*topology.Topology, error) { return record, nil }
	f.handler = testHandlerWithDev(t, ".", dev)
	if rec := post(t, f.handler, "/api/development/order-flow"); rec.Code != http.StatusOK {
		t.Fatalf("load: %s", rec.Body.String())
	}
	return f
}

func put(t *testing.T, h http.Handler, path, body string) *httptest.ResponseRecorder {
	t.Helper()
	rec := httptest.NewRecorder()
	req := httptest.NewRequest(http.MethodPut, path, strings.NewReader(body))
	h.ServeHTTP(rec, req)
	return rec
}

func del(t *testing.T, h http.Handler, path string) *httptest.ResponseRecorder {
	t.Helper()
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, httptest.NewRequest(http.MethodDelete, path, nil))
	return rec
}

// The full CRUD round trip: absent library lists as [], PUT creates the
// directory and file, single GET returns content with flags, DELETE
// removes it.
func TestLibraryCRUD(t *testing.T) {
	f := newLibraryFixture(t)

	rec := get(t, f.handler, "/api/development/library/src/order-flow")
	if got := strings.TrimSpace(rec.Body.String()); got != "[]" {
		t.Fatalf("empty library = %q, want []", got)
	}

	rec = put(t, f.handler, "/api/development/library/src/order-flow/order.json", `{"sku":"1"}`)
	if rec.Code != http.StatusOK {
		t.Fatalf("PUT status = %d: %s", rec.Code, rec.Body.String())
	}

	rec = get(t, f.handler, "/api/development/library/src/order-flow")
	var entries []libraryEntry
	if err := json.Unmarshal(rec.Body.Bytes(), &entries); err != nil {
		t.Fatalf("list body: %v", err)
	}
	if len(entries) != 1 || entries[0].Name != "order.json" || entries[0].Size != int64(len(`{"sku":"1"}`)) {
		t.Errorf("entries = %+v", entries)
	}

	rec = get(t, f.handler, "/api/development/library/src/order-flow/order.json")
	var file libraryFile
	if err := json.Unmarshal(rec.Body.Bytes(), &file); err != nil {
		t.Fatalf("file body: %v", err)
	}
	if file.Content != `{"sku":"1"}` || file.Truncated || file.Binary {
		t.Errorf("file = %+v", file)
	}

	rec = del(t, f.handler, "/api/development/library/src/order-flow/order.json")
	if rec.Code != http.StatusNoContent {
		t.Errorf("DELETE status = %d, want 204", rec.Code)
	}
	rec = get(t, f.handler, "/api/development/library/src/order-flow")
	if got := strings.TrimSpace(rec.Body.String()); got != "[]" {
		t.Errorf("after delete = %q, want []", got)
	}
}

// The schema rides the single-file GET when the connector's join resolves
// to exactly one contract, and is omitted when the connector has no
// contracted topic (src uses nothing) — never guessed.
func TestLibraryFileSchemaJoin(t *testing.T) {
	f := newLibraryFixture(t)
	put(t, f.handler, "/api/development/library/dst/order-flow/order.json", `{}`)
	put(t, f.handler, "/api/development/library/src/order-flow/other.json", `{}`)

	rec := get(t, f.handler, "/api/development/library/dst/order-flow/order.json")
	var withSchema libraryFile
	if err := json.Unmarshal(rec.Body.Bytes(), &withSchema); err != nil {
		t.Fatalf("body: %v", err)
	}
	if string(withSchema.Schema) != `{"type":"object"}` {
		t.Errorf("schema = %s", withSchema.Schema)
	}

	rec = get(t, f.handler, "/api/development/library/src/order-flow/other.json")
	var without libraryFile
	if err := json.Unmarshal(rec.Body.Bytes(), &without); err != nil {
		t.Fatalf("body: %v", err)
	}
	if without.Schema != nil {
		t.Errorf("schema = %s, want omitted", without.Schema)
	}
}

// Binary content is classified server-side (NUL bytes), text is not.
func TestLibraryBinaryFlag(t *testing.T) {
	f := newLibraryFixture(t)
	put(t, f.handler, "/api/development/library/src/order-flow/payload.bin", "a\x00b")
	put(t, f.handler, "/api/development/library/src/order-flow/payload.json", "{}")

	rec := get(t, f.handler, "/api/development/library/src/order-flow/payload.bin")
	var bin libraryFile
	if err := json.Unmarshal(rec.Body.Bytes(), &bin); err != nil {
		t.Fatalf("body: %v", err)
	}
	if !bin.Binary {
		t.Errorf("binary flag = false for NUL-containing content")
	}

	rec = get(t, f.handler, "/api/development/library/src/order-flow/payload.json")
	var txt libraryFile
	if err := json.Unmarshal(rec.Body.Bytes(), &txt); err != nil {
		t.Fatalf("body: %v", err)
	}
	if txt.Binary {
		t.Errorf("binary flag = true for plain text")
	}
}

// Containment is element-aware and symlink-resolved: traversal, absolute
// paths, sibling prefixes, and planted symlinks all fail without touching
// anything outside the library.
func TestLibraryContainment(t *testing.T) {
	f := newLibraryFixture(t)
	outside := filepath.Join(f.systemDir, "test", "outside.txt")
	if err := os.WriteFile(outside, []byte("secret"), 0o644); err != nil {
		t.Fatal(err)
	}

	escapes := []string{
		"/api/development/library/src/order-flow/..%2F..%2Foutside.txt",
		"/api/development/library/src/order-flow/..%2Foutside.txt",
	}
	for _, path := range escapes {
		if rec := get(t, f.handler, path); rec.Code == http.StatusOK {
			t.Errorf("GET %s = 200, want refusal", path)
		}
		if rec := put(t, f.handler, path, "x"); rec.Code == http.StatusOK {
			t.Errorf("PUT %s = 200, want refusal", path)
		}
	}
	if data, _ := os.ReadFile(outside); string(data) != "secret" {
		t.Errorf("outside file modified: %q", data)
	}

	// A symlink inside the library pointing outside it is resolved, then
	// refused.
	libDir := filepath.Join(f.library, "src")
	if err := os.MkdirAll(libDir, 0o755); err != nil {
		t.Fatal(err)
	}
	link := filepath.Join(libDir, "link.txt")
	if err := os.Symlink(outside, link); err != nil {
		t.Skipf("symlinks unavailable: %v", err)
	}
	if rec := get(t, f.handler, "/api/development/library/src/order-flow/link.txt"); rec.Code == http.StatusOK {
		t.Errorf("symlinked GET = 200, want refusal")
	}
	if rec := put(t, f.handler, "/api/development/library/src/order-flow/link.txt", "x"); rec.Code == http.StatusOK {
		t.Errorf("symlinked PUT = 200, want refusal")
	}
}

// Writes past the cap fail cleanly and leave no partial file.
func TestLibraryWriteCap(t *testing.T) {
	f := newLibraryFixture(t)
	big := strings.Repeat("x", maxLibraryBytes+1)
	rec := put(t, f.handler, "/api/development/library/src/order-flow/big.json", big)
	if rec.Code != http.StatusRequestEntityTooLarge {
		t.Errorf("status = %d, want 413", rec.Code)
	}
	if _, err := os.Stat(filepath.Join(f.library, "src", "big.json")); err == nil {
		t.Error("partial file exists after over-cap write")
	}
}

// Unknown systems, unknown connectors, and connectors whose rootPath
// failed validation all 404 with the shared error shape.
func TestLibraryUnknowns404(t *testing.T) {
	f := newLibraryFixture(t)
	for _, path := range []string{
		"/api/development/library/src/nope",
		"/api/development/library/nope/order-flow",
		"/api/development/library/src/order-flow",
		"/api/development/library/src/order-flow/x.json",
	} {
		// The last two are valid list/unknown-file shapes handled per case.
		rec := del(t, f.handler, path+"/missing.json")
		if rec.Code != http.StatusNotFound {
			t.Errorf("DELETE %s = %d, want 404", path, rec.Code)
		}
	}
}

// Inject copies the library file into the watched dir atomically and names
// the destination; a missing watched dir is the expected error when the
// system has not run yet.
func TestInject(t *testing.T) {
	f := newLibraryFixture(t)
	put(t, f.handler, "/api/development/library/src/order-flow/big-order.json", `{"sku":"42"}`)

	// The watched dir does not exist until the system runs.
	rec := post(t, f.handler, "/api/development/inject/src/order-flow/big-order.json")
	if rec.Code != http.StatusConflict {
		t.Fatalf("inject without watched dir = %d, want 409", rec.Code)
	}
	var errBody map[string]string
	if err := json.Unmarshal(rec.Body.Bytes(), &errBody); err != nil {
		t.Fatalf("error body: %v", err)
	}
	if !strings.Contains(errBody["error"], "does not exist") ||
		!strings.Contains(errBody["error"], "start the system") {
		t.Errorf("error = %q, want missing-dir with remediation", errBody["error"])
	}

	// The system ran: its connector created the watched dir.
	watchedDir := filepath.Join(f.watched, "src")
	if err := os.MkdirAll(watchedDir, 0o755); err != nil {
		t.Fatal(err)
	}
	rec = post(t, f.handler, "/api/development/inject/src/order-flow/big-order.json")
	if rec.Code != http.StatusOK {
		t.Fatalf("inject = %d: %s", rec.Code, rec.Body.String())
	}
	data, err := os.ReadFile(filepath.Join(watchedDir, "big-order.json"))
	if err != nil || string(data) != `{"sku":"42"}` {
		t.Errorf("injected content = %q, %v", data, err)
	}

	// Re-inject overwrites via rename (the watched dir is runtime state).
	put(t, f.handler, "/api/development/library/src/order-flow/big-order.json", `{"sku":"43"}`)
	post(t, f.handler, "/api/development/inject/src/order-flow/big-order.json")
	data, _ = os.ReadFile(filepath.Join(watchedDir, "big-order.json"))
	if string(data) != `{"sku":"43"}` {
		t.Errorf("re-injected content = %q", data)
	}
}

