// readLibrary is the test counterpart of the editor's file GET: it
// decodes the wire format rather than the Go type, because the schema is
// compacted for the wire and the Go type would hide the difference.
func readLibrary(t *testing.T, h http.Handler, path string) map[string]any {
	t.Helper()
	rec := get(t, h, path)
	var body map[string]any
	if err := json.Unmarshal(rec.Body.Bytes(), &body); err != nil {
		t.Fatalf("GET %s: %v\n%s", path, err, rec.Body.String())
	}
	return body
}

