package dashboard

import (
	"net/http"
	"os"
	"time"
)

// outputFile is one file in a connector's watched directory.
type outputFile struct {
	Name    string    `json:"name"`
	Size    int64     `json:"size"`
	ModTime time.Time `json:"modTime"`
}

// outputsReport is the listing the Test view's refresh button reads: the
// current contents of one connector's watched directory. ScannedAt says
// when the scan ran so the UI is honest that this is a point-in-time read,
// not a live feed. Exists is false when the watched directory is not there
// — the system has not run yet — which is a state to show, not an error
// (R6): Files is empty and the pane explains why.
type outputsReport struct {
	Connector string       `json:"connector"`
	RootPath  string       `json:"rootPath"`
	Exists    bool         `json:"exists"`
	ScannedAt time.Time    `json:"scannedAt"`
	Files     []outputFile `json:"files"`
}

// outputsContent is one watched-dir file's content for the compare view,
// with the same honesty flags the library editor uses.
type outputsContent struct {
	Name      string `json:"name"`
	Content   string `json:"content"`
	Truncated bool   `json:"truncated,omitempty"`
	Binary    bool   `json:"binary,omitempty"`
}

// handleOutputs serves the out-connector listing or one file's content.
// The scan is synchronous at request time — readdir plus stat over a local
// dev directory costs milliseconds — which is what makes the dumb-browser
// posture work without any background watcher: there is no snapshot to go
// stale, no goroutine to shut down, and nothing to re-key when the record
// reloads.
func (s *apiServer) handleOutputs(w http.ResponseWriter, r *http.Request) {
	connector := r.PathValue("connector")
	systemPath, fileName, ok := s.splitSystemWildcard(w, r.PathValue("path"))
	if !ok {
		return
	}

	rootPath, err := s.connectorRootPath(systemPath, connector)
	if err != nil {
		writeError(w, http.StatusNotFound, err.Error())
		return
	}

	if fileName == "" {
		s.listOutputs(w, connector, rootPath)
		return
	}
	s.readOutput(w, rootPath, fileName)
}

// listOutputs scans the watched dir now. A missing dir lists as
// exists:false with empty files — plain readdir gives the appear-when-the-
// system-starts behavior for free, with no special handling.
func (s *apiServer) listOutputs(w http.ResponseWriter, connector, rootPath string) {
	report := outputsReport{
		Connector: connector,
		RootPath:  rootPath,
		ScannedAt: time.Now(),
		Files:     []outputFile{},
	}
	entries, err := libraryFiles(rootPath)
	switch {
	case err != nil:
		// Missing dir is the common case (system not started); anything
		// else unreadable reports the same way — the UI cannot act on the
		// distinction and the developer's terminal can.
		report.Exists = false
	default:
		report.Exists = true
		for _, e := range entries {
			report.Files = append(report.Files, outputFile(e))
		}
	}
	writeJSON(w, http.StatusOK, report)
}

// readOutput serves one file's content, contained to the watched dir with
// the library's discipline: symlink-resolved, element-aware, links refused.
func (s *apiServer) readOutput(w http.ResponseWriter, rootPath, name string) {
	base, err := canonicalDir(rootPath)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "resolve watched directory: "+err.Error())
		return
	}
	candidate := joinSlash(base, name)
	resolved, err := canonicalDir(candidate)
	if err != nil {
		writeError(w, http.StatusNotFound, "resolve "+name+": "+err.Error())
		return
	}
	if !withinDir(base, resolved) || resolved == base {
		writeError(w, http.StatusBadRequest, "file "+name+" escapes the watched directory")
		return
	}
	if info, statErr := os.Lstat(candidate); statErr == nil && info.Mode()&os.ModeSymlink != 0 {
		writeError(w, http.StatusBadRequest, "refusing to follow symlink "+name)
		return
	}
	data, err := os.ReadFile(resolved)
	if err != nil {
		writeError(w, http.StatusNotFound, "read "+name+": "+err.Error())
		return
	}
	out := outputsContent{Name: name}
	out.Content, out.Truncated, out.Binary = cappedText(data)
	writeJSON(w, http.StatusOK, out)
}

// joinSlash joins a slash-separated API file name onto a base directory.
func joinSlash(base, name string) string {
	return base + string(os.PathSeparator) + filepathFromSlash(name)
}

