package dashboard

import (
	"encoding/json"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// The listing is a synchronous scan: what is on disk at request time is
// what the response shows, and a missing watched dir is an exists:false
// state, never an error. Covers AE2's amended delivery: no push, no
// snapshot — the refresh button is the cursor.
func TestOutputsScanOnDemand(t *testing.T) {
	f := newLibraryFixture(t)
	watchedDir := filepath.Join(f.watched, "dst")

	rec := get(t, f.handler, "/api/development/outputs/dst/order-flow")
	var report outputsReport
	if err := json.Unmarshal(rec.Body.Bytes(), &report); err != nil {
		t.Fatalf("body: %v", err)
	}
	if report.Exists || len(report.Files) != 0 {
		t.Errorf("missing dir: report = %+v, want exists:false, no files", report)
	}
	if report.ScannedAt.IsZero() {
		t.Error("scannedAt missing")
	}

	// The system ran and produced output; the next refresh sees it.
	if err := os.MkdirAll(watchedDir, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(watchedDir, "result-001.json"), []byte(`{"ok":true}`), 0o644); err != nil {
		t.Fatal(err)
	}
	rec = get(t, f.handler, "/api/development/outputs/dst/order-flow")
	if err := json.Unmarshal(rec.Body.Bytes(), &report); err != nil {
		t.Fatalf("body: %v", err)
	}
	if !report.Exists || len(report.Files) != 1 || report.Files[0].Name != "result-001.json" {
		t.Errorf("report = %+v", report)
	}

	// Deleted between refreshes: gone from the next scan.
	if err := os.Remove(filepath.Join(watchedDir, "result-001.json")); err != nil {
		t.Fatal(err)
	}
	rec = get(t, f.handler, "/api/development/outputs/dst/order-flow")
	if err := json.Unmarshal(rec.Body.Bytes(), &report); err != nil {
		t.Fatalf("body: %v", err)
	}
	if len(report.Files) != 0 {
		t.Errorf("after delete: files = %+v", report.Files)
	}
}

// Single-file content rides the same containment and honesty rules as the
// library read.
func TestOutputsReadFile(t *testing.T) {
	f := newLibraryFixture(t)
	watchedDir := filepath.Join(f.watched, "dst")
	if err := os.MkdirAll(watchedDir, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(watchedDir, "result.json"), []byte(`{"ok":true}`), 0o644); err != nil {
		t.Fatal(err)
	}

	rec := get(t, f.handler, "/api/development/outputs/dst/order-flow/result.json")
	var content outputsContent
	if err := json.Unmarshal(rec.Body.Bytes(), &content); err != nil {
		t.Fatalf("body: %v", err)
	}
	if content.Content != `{"ok":true}` || content.Truncated || content.Binary {
		t.Errorf("content = %+v", content)
	}

	// Deleted after listing: the content GET 404s.
	if rec := get(t, f.handler, "/api/development/outputs/dst/order-flow/nope.json"); rec.Code != http.StatusNotFound {
		t.Errorf("missing file = %d, want 404", rec.Code)
	}

	// A symlink inside the watched dir pointing outside it is refused.
	outside := filepath.Join(f.watched, "outside.txt")
	if err := os.WriteFile(outside, []byte("secret"), 0o644); err != nil {
		t.Fatal(err)
	}
	if err := os.Symlink(outside, filepath.Join(watchedDir, "link.txt")); err != nil {
		t.Skipf("symlinks unavailable: %v", err)
	}
	if rec := get(t, f.handler, "/api/development/outputs/dst/order-flow/link.txt"); rec.Code == http.StatusOK {
		t.Errorf("symlinked read = 200, want refusal")
	}
	// Traversal is refused.
	if rec := get(t, f.handler, "/api/development/outputs/dst/order-flow/..%2Foutside.txt"); rec.Code == http.StatusOK {
		t.Errorf("traversal read = 200, want refusal")
	}
}

// An unknown connector or an unloaded system is a 404, same as the other
// development file endpoints.
func TestOutputsUnknowns(t *testing.T) {
	f := newLibraryFixture(t)
	if rec := get(t, f.handler, "/api/development/outputs/nope/order-flow"); rec.Code != http.StatusNotFound {
		t.Errorf("unknown connector = %d, want 404", rec.Code)
	}
	if rec := get(t, f.handler, "/api/development/outputs/dst/nope"); rec.Code != http.StatusNotFound {
		t.Errorf("unknown system = %d, want 404", rec.Code)
	}

	// Unloaded system: build a second handler whose provider never runs.
	t.Chdir(t.TempDir())
	writeSystemHost(t, "sys/system-host", "sys")
	h := testHandlerWithDev(t, ".", nil)
	rec := get(t, h, "/api/development/outputs/src/sys")
	if rec.Code != http.StatusNotFound {
		t.Errorf("unloaded system = %d, want 404", rec.Code)
	}
	var body map[string]string
	if err := json.Unmarshal(rec.Body.Bytes(), &body); err != nil ||
		!strings.Contains(body["error"], "not loaded") {
		t.Errorf("body = %v, %v", body, err)
	}
}

