// Development topology and file testing (internal/dashboard/development.go
// and library.go/outputs.go). The development record comes from the system
// host's optional `graph-development` verb and is loaded only on explicit
// POST — a cold verb run builds the host first, so GET never computes.

/** A connector's local watched directory, declared by the development
 *  topology's files[] section. Direction lives on the record's connectors[],
 *  not here. */
export interface DevelopmentFile {
  connector: string
  /** Absolute on the host's machine; validated to lie within the system
   *  host's tree before the record is served. */
  rootPath: string
}

/** The development section of a topology record — present only on records
 *  emitted by the graph-development verb. */
export interface DevelopmentSection {
  files?: DevelopmentFile[]
}

/** The development record as served: the deployed Topology shape plus the
 *  development section. */
export interface DevelopmentTopology extends Omit<Topology, 'path' | 'messageDocs'> {
  development?: DevelopmentSection
}

/** Which of the four development-record states the server holds for one
 *  system. */
export type DevelopmentState = 'not-loaded' | 'loaded' | 'not-declared' | 'error'

/** The GET/POST /api/development/{path} payload. GET serves the cached
 *  state (never computing); POST runs the verb and returns the fresh one. */
export interface DevelopmentReport {
  path: string
  state: DevelopmentState
  system?: string
  topology?: DevelopmentTopology
  /** The verb's own message, verbatim, when state is "error". */
  error?: string
  /** Connectors whose declared rootPath lies outside the system tree,
   *  keyed by connector name. Their file endpoints refuse; the rest of the
   *  record loads normally. */
  connectorErrors?: Record<string, string>
}

/** One entry of the Test view's system selector: a scaffolded system host.
 *  Sourced from the workspace scan, so systems with a broken deployed graph
 *  or no development verb stay selectable. */
export interface DevelopmentSystem {
  path: string
  name: string
}

/** One file in a connector's staging library. */
export interface LibraryEntry {
  name: string
  size: number
  modTime: string
}

/** One library file's content with the honesty flags the editor needs:
 *  `truncated` marks a read cut at the server's cap (save is refused —
 *  writing the buffer back would destroy content past the cap); `binary`
 *  marks undecodable content (not editable, still injectable from the
 *  list). `schema` is the connector's contract schema when the join
 *  resolves to exactly one — a read-only reference, never a validator. */
export interface LibraryFile {
  name: string
  content: string
  truncated?: boolean
  binary?: boolean
  schema?: JsonSchema
}

/** The inject result: the destination the file was copied to. */
export interface InjectResult {
  injected: string
  destination: string
}

/** One file in a connector's watched directory. */
export interface OutputFile {
  name: string
  size: number
  modTime: string
}

/** The current contents of one connector's watched directory, scanned
 *  synchronously at request time. `exists` is false when the system has
 *  not run yet — a state to show, not an error. `scannedAt` says when the
 *  scan ran: this is a point-in-time read, not a live feed. */
export interface OutputsReport {
  connector: string
  rootPath: string
  exists: boolean
  scannedAt: string
  files: OutputFile[]
}

/** One watched-dir file's content for the compare view. */
export interface OutputsContent {
  name: string
  content: string
  truncated?: boolean
  binary?: boolean
}

async function requestJSON<T>(url: string, init?: RequestInit): Promise<T> {

  health: () => getJSON<Health>('/api/health'),
  /** Every scaffolded system host, for the Test view's selector. */
  developmentSystems: () => getJSON<DevelopmentSystem[]>('/api/development'),
  /** One system's cached development state. Never runs the verb. */
  development: (path: string) => getJSON<DevelopmentReport>(`/api/development/${path}`),
  /** Run one system's graph-development verb and return the fresh state —
   *  can take minutes on a cold build. */
  loadDevelopment: (path: string) =>
    requestJSON<DevelopmentReport>(`/api/development/${path}`, { method: 'POST' }),
  /** One connector's staging library ([] when not created yet). */
  library: (connector: string, systemPath: string) =>
    getJSON<LibraryEntry[]>(`/api/development/library/${connector}/${systemPath}`),
  /** One library file's content, flags, and reference schema. */
  libraryFile: (connector: string, systemPath: string, name: string) =>
    getJSON<LibraryFile>(`/api/development/library/${connector}/${systemPath}/${name}`),
  /** Create or replace one library file (text body, capped server-side). */
  saveLibraryFile: (connector: string, systemPath: string, name: string, content: string) =>
    requestJSON<LibraryEntry>(`/api/development/library/${connector}/${systemPath}/${name}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'text/plain; charset=utf-8' },
      body: content,
    }),
  deleteLibraryFile: (connector: string, systemPath: string, name: string) =>
    requestJSON<void>(`/api/development/library/${connector}/${systemPath}/${name}`, {
      method: 'DELETE',
    }),
  /** Copy a library file into the connector's watched directory. */
  inject: (connector: string, systemPath: string, name: string) =>
    requestJSON<InjectResult>(`/api/development/inject/${connector}/${systemPath}/${name}`, {
      method: 'POST',
    }),
  /** The current contents of a connector's watched directory (scanned on demand). */
  outputs: (connector: string, systemPath: string) =>
    getJSON<OutputsReport>(`/api/development/outputs/${connector}/${systemPath}`),
  /** One watched-dir file's content, for the compare view. */
  outputContent: (connector: string, systemPath: string, name: string) =>
    getJSON<OutputsContent>(`/api/development/outputs/${connector}/${systemPath}/${name}`),
}

