import { useCallback, useEffect, useMemo, useState } from 'react'
import {
  api,
  type DevelopmentReport,
  type DevelopmentSystem,
  type DevelopmentTopology,
  type JsonSchema,
  type LibraryEntry,
  type OutputsReport,
} from '../api'
import { Combobox } from './Combobox'

// TestView is the per-system file-testing console: author payloads in a
// connector's staging library, inject one into its watched directory, and
// compare what the running system writes back. The browser stays dumb —
// every expensive thing (the development record, the output scan) happens
// on an explicit click, never on a poll or a push.
//
// Accepted postures, stated once rather than re-litigated per interaction:
// save is last-write-wins (no etag/mtime check); endpoint errors render in
// the pane that initiated them; inject overwrites an existing watched-dir
// file without asking (it is runtime state); the layout assumes a desktop
// dev-tool viewport.

interface ConnectorInfo {
  name: string
  rootPath: string
  /** Joined from the record's connectors[]; empty when the connector is
   *  absent there (an "ungrouped" entry). */
  directions: string[]
  /** Validation failure from the record load, when the rootPath escaped
   *  the system tree. */
  error?: string
}

interface PendingConfirm {
  message: string
  action: () => void
}

export function TestView() {
  const [systems, setSystems] = useState<DevelopmentSystem[] | null>(null)
  const [system, setSystem] = useState<string | null>(null)
  const [report, setReport] = useState<DevelopmentReport | null>(null)
  const [loading, setLoading] = useState(false)
  const [connector, setConnector] = useState<string | null>(null)
  const [error, setError] = useState<string | null>(null)

  // System selector: the workspace scan, not /api/topology — a system with
  // a broken deployed graph but a working development verb must stay
  // reachable.
  useEffect(() => {
    api
      .developmentSystems()
      .then(setSystems)
      .catch((e: unknown) => setError(errText(e)))
  }, [])

  useEffect(() => {
    if (systems && systems.length > 0 && !system) setSystem(systems[0].path)
  }, [systems, system])

  // The cached state comes with the selection; it never computes server-side.
  useEffect(() => {
    if (!system) return
    let current = true
    setConnector(null)
    api
      .development(system)
      .then((r) => {
        if (current) setReport(r)
      })
      .catch((e: unknown) => {
        if (current) setError(errText(e))
      })
    return () => {
      current = false
    }
  }, [system])

  const load = useCallback(() => {
    if (!system) return
    setLoading(true)
    setError(null)
    api
      .loadDevelopment(system)
      .then(setReport)
      .catch((e: unknown) => setError(errText(e)))
      .finally(() => setLoading(false))
  }, [system])

  const connectors = useMemo(
    () => (report?.topology ? groupConnectors(report.topology, report.connectorErrors) : null),
    [report],
  )

  return (
    <div className="test">
      <div className="test-toolbar">
        <span className="flow-toolbar-label">System</span>
        <Combobox
          value={system}
          options={(systems ?? []).map((s) => ({ value: s.path, label: s.name }))}
          onChange={(v) => {
            setSystem(v)
            setReport(null)
          }}
          placeholder="Select a system…"
        />
      </div>
      {error && <div className="banner error">{error}</div>}
      {!report || report.state === 'not-loaded' ? (
        <div className="test-state">
          <p className="empty">
            The development topology has not been loaded for this system.
          </p>
          <button className="flow-refresh" onClick={load} disabled={!system || loading}>
            {loading
              ? 'Loading development topology… (a cold build can take minutes)'
              : 'Load development topology'}
          </button>
        </div>
      ) : report.state === 'not-declared' ? (
        <div className="test-state">
          <p className="empty">
            This system declares no <code>graph-development</code> task — file testing is
            only available for systems with a development topology. See the graph task
            contract for how to add one.
          </p>
        </div>
      ) : report.state === 'error' ? (
        <div className="test-state">
          <div className="banner error">{report.error}</div>
          <button className="flow-refresh" onClick={load} disabled={loading}>
            {loading ? 'Retrying…' : 'Retry'}
          </button>
        </div>
      ) : connectors ? (
        <LoadedView
          systemPath={report.path}
          connectors={connectors}
          connector={connector}
          onSelectConnector={setConnector}
          onReload={load}
          reloading={loading}
        />
      ) : null}
    </div>
  )
}

// groupConnectors joins development.files[] against the record's
// connectors[] for direction. Entries whose connector is absent from
// connectors[] — or wired both ways — land in "ungrouped" rather than
// being forced into a pane.
function groupConnectors(
  t: DevelopmentTopology,
  connectorErrors?: Record<string, string>,
): { in: ConnectorInfo[]; out: ConnectorInfo[]; ungrouped: ConnectorInfo[] } {
  const groups = { in: [] as ConnectorInfo[], out: [] as ConnectorInfo[], ungrouped: [] as ConnectorInfo[] }
  for (const f of t.development?.files ?? []) {
    const declared = t.connectors?.find((c) => c.name === f.connector)
    const info: ConnectorInfo = {
      name: f.connector,
      rootPath: f.rootPath,
      directions: declared?.directions ?? [],
      error: connectorErrors?.[f.connector],
    }
    if (info.directions.length === 1 && info.directions[0] === 'in') groups.in.push(info)
    else if (info.directions.length === 1 && info.directions[0] === 'out') groups.out.push(info)
    else groups.ungrouped.push(info)
  }
  return groups
}

// LoadedView is the three-pane console: connectors (left), library and
// editor (center), outputs and compare (right).
function LoadedView({
  systemPath,
  connectors,
  connector,
  onSelectConnector,
  onReload,
  reloading,
}: {
  systemPath: string
  connectors: { in: ConnectorInfo[]; out: ConnectorInfo[]; ungrouped: ConnectorInfo[] }
  connector: string | null
  onSelectConnector: (name: string) => void
  onReload: () => void
  reloading: boolean
}) {
  const all = [...connectors.in, ...connectors.out, ...connectors.ungrouped]
  const selected = all.find((c) => c.name === connector) ?? null
  const [confirm, setConfirm] = useState<PendingConfirm | null>(null)
  const [dirty, setDirty] = useState(false)

  // Switching connectors with a dirty editor asks first. The guard covers
  // connector and file switches; switching the top-level view away is out
  // of scope (the dirty state lives here and leaving discards it).
  const guardedSelect = (name: string) => {
    if (name === connector) return
    if (dirty) {
      setConfirm({
        message: 'Discard unsaved changes?',
        action: () => {
          setDirty(false)
          onSelectConnector(name)
        },
      })
      return
    }
    onSelectConnector(name)
  }

  return (
    <div className="test-panes">
      <aside className="test-connectors">
        <ConnectorGroup title="In" items={connectors.in} selected={connector} onSelect={guardedSelect} />
        <ConnectorGroup title="Out" items={connectors.out} selected={connector} onSelect={guardedSelect} />
        {connectors.ungrouped.length > 0 && (
          <ConnectorGroup title="Ungrouped" items={connectors.ungrouped} selected={connector} onSelect={guardedSelect} />
        )}
        <button className="flow-refresh test-reload" onClick={onReload} disabled={reloading}>
          {reloading ? 'Reloading…' : 'Reload development topology'}
        </button>
      </aside>
      <section className="test-center">
        {selected ? (
          <LibraryPane
            key={`${systemPath}/${selected.name}`}
            systemPath={systemPath}
            connector={selected}
            confirm={confirm}
            setConfirm={setConfirm}
            dirty={dirty}
            setDirty={setDirty}
          />
        ) : (
          <p className="empty">Select a connector to author and inject test payloads.</p>
        )}
      </section>
      <section className="test-right">
        {selected ? (
          <OutputsPane key={`out/${systemPath}/${selected.name}`} systemPath={systemPath} connector={selected} />
        ) : (
          <p className="empty">Outputs appear here after a run.</p>
        )}
      </section>
    </div>
  )
}

function ConnectorGroup({
  title,
  items,
  selected,
  onSelect,
}: {
  title: string
  items: ConnectorInfo[]
  selected: string | null
  onSelect: (name: string) => void
}) {
  if (items.length === 0) return null
  return (
    <div className="test-connector-group">
      <div className="flow-toolbar-label">{title}</div>
      {items.map((c) => (
        <button
          key={c.name}
          className={`test-connector${selected === c.name ? ' active' : ''}`}
          onClick={() => onSelect(c.name)}
          title={c.error ?? c.rootPath}
        >
          <span className="test-connector-name">{c.name}</span>
          {c.error ? (
            <span className="test-connector-flag error" title={c.error}>invalid rootPath</span>
          ) : (
            c.directions.length > 0 && <span className="test-connector-flag">{c.directions.join(',')}</span>
          )}
        </button>
      ))}
    </div>
  )
}

// LibraryPane is the authoring surface: the staging library list, the
// editor, and the inject action. Dirty state is lifted to LoadedView so
// connector switches can be guarded.
function LibraryPane({
  systemPath,
  connector,
  confirm,
  setConfirm,
  dirty,
  setDirty,
}: {
  systemPath: string
  connector: ConnectorInfo
  confirm: PendingConfirm | null
  setConfirm: (c: PendingConfirm | null) => void
  dirty: boolean
  setDirty: (d: boolean) => void
}) {
  const [files, setFiles] = useState<LibraryEntry[] | null>(null)
  const [file, setFile] = useState<string | null>(null)
  const [buffer, setBuffer] = useState('')
  const [savedBuffer, setSavedBuffer] = useState('')
  const [truncated, setTruncated] = useState(false)
  const [binary, setBinary] = useState(false)
  const [schema, setSchema] = useState<JsonSchema | null>(null)
  const [newName, setNewName] = useState('')
  const [notice, setNotice] = useState<string | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [injecting, setInjecting] = useState(false)

  const refresh = useCallback(() => {
    api
      .library(connector.name, systemPath)
      .then(setFiles)
      .catch((e: unknown) => setError(errText(e)))
  }, [connector.name, systemPath])

  useEffect(refresh, [refresh])

  const open = useCallback(
    (name: string) => {
      setError(null)
      setNotice(null)
      api
        .libraryFile(connector.name, systemPath, name)
        .then((f) => {
          setFile(name)
          setBuffer(f.content)
          setSavedBuffer(f.content)
          setDirty(false)
          setTruncated(!!f.truncated)
          setBinary(!!f.binary)
          setSchema(f.schema ?? null)
        })
        .catch((e: unknown) => setError(errText(e)))
    },
    [connector.name, systemPath, setDirty],
  )

  const guardedOpen = (name: string) => {
    if (dirty && name !== file) {
      setConfirm({ message: 'Discard unsaved changes?', action: () => open(name) })
      return
    }
    open(name)
  }

  const save = () => {
    if (!file || truncated || binary) return
    setError(null)
    api
      .saveLibraryFile(connector.name, systemPath, file, buffer)
      .then(() => {
        setSavedBuffer(buffer)
        setDirty(false)
        setNotice(`saved ${file}`)
        refresh()
      })
      .catch((e: unknown) => setError(errText(e)))
  }

  const create = () => {
    const name = newName.trim()
    if (!name) return
    const full = name.endsWith('.json') ? name : `${name}.json`
    setNewName('')
    api
      .saveLibraryFile(connector.name, systemPath, full, '')
      .then(() => {
        refresh()
        open(full)
      })
      .catch((e: unknown) => setError(errText(e)))
  }

  const remove = (name: string) => {
    setConfirm({
      message: `Delete ${name}?`,
      action: () => {
        api
          .deleteLibraryFile(connector.name, systemPath, name)
          .then(() => {
            if (file === name) {
              setFile(null)
              setBuffer('')
              setSavedBuffer('')
              setDirty(false)
            }
            refresh()
          })
          .catch((e: unknown) => setError(errText(e)))
      },
    })
  }

  const inject = (name: string) => {
    setInjecting(true)
    setError(null)
    setNotice(null)
    api
      .inject(connector.name, systemPath, name)
      .then((r) =>
        setNotice(`copied to ${r.destination} (overwrites any existing file) — refresh outputs to see what the system wrote`),
      )
      .catch((e: unknown) => setError(errText(e)))
      .finally(() => setInjecting(false))
  }

  return (
    <div className="test-library">
      <div className="test-pane-title">
        Library <code>test/library/{connector.name}/</code>
      </div>
      {confirm && (
        <div className="test-confirm">
          <span>{confirm.message}</span>
          <button
            className="flow-refresh"
            onClick={() => {
              confirm.action()
              setConfirm(null)
            }}
          >
            Confirm
          </button>
          <button className="flow-refresh" onClick={() => setConfirm(null)}>
            Keep editing
          </button>
        </div>
      )}
      {error && <div className="banner error">{error}</div>}
      {notice && <div className="banner test-notice">{notice}</div>}
      {connector.error && <div className="banner error">{connector.error}</div>}
      <div className="test-newfile">
        <input
          value={newName}
          onChange={(e) => setNewName(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && create()}
          placeholder="new-payload.json"
          aria-label="New file name"
        />
        <button className="flow-refresh" onClick={create} disabled={!newName.trim()}>
          New file
        </button>
      </div>
      {files && files.length === 0 && (
        <p className="empty">
          No test payloads yet. Create one above — files live in{' '}
          <code>test/library/{connector.name}/</code> and are meant to be committed.
        </p>
      )}
      <ul className="test-filelist">
        {(files ?? []).map((f) => (
          <li key={f.name} className={file === f.name ? 'active' : ''}>
            <button className="test-file" onClick={() => guardedOpen(f.name)}>
              {f.name}
            </button>
            <button className="test-file-action" onClick={() => inject(f.name)} disabled={injecting} title="Copy into the watched directory">
              Inject
            </button>
            <button className="test-file-action" onClick={() => remove(f.name)} title="Delete from the library">
              Delete
            </button>
          </li>
        ))}
      </ul>
      {file && (
        <div className="test-editor">
          <div className="test-editor-head">
            <span className="test-editor-name">{file}</span>
            {dirty && <span className="test-connector-flag">unsaved</span>}
            <button
              className="flow-refresh"
              onClick={save}
              disabled={!dirty || truncated || binary}
              title={truncated ? 'Truncated files cannot be saved' : binary ? 'Binary files cannot be edited' : undefined}
            >
              Save
            </button>
          </div>
          {truncated && (
            <div className="banner error">
              This file exceeds the read cap and is shown truncated; saving is disabled so
              content past the cap is not destroyed.
            </div>
          )}
          {binary && <div className="banner test-notice">Binary file — not editable. Inject from the list still works.</div>}
          {!binary && (
            <textarea
              value={buffer}
              onChange={(e) => {
                setBuffer(e.target.value)
                setDirty(e.target.value !== savedBuffer)
              }}
              spellCheck={false}
              aria-label={`Edit ${file}`}
            />
          )}
          {schema && (
            <details className="test-schema">
              <summary>Contract schema (reference only — never validated)</summary>
              <pre>{JSON.stringify(schema, null, 2)}</pre>
            </details>
          )}
        </div>
      )}
    </div>
  )
}

// OutputsPane lists the connector's watched directory on demand and drives
// the compare view: pick an output, then a library file, and the line diff
// renders. Diffing always uses saved disk content — never a dirty buffer.
function OutputsPane({ systemPath, connector }: { systemPath: string; connector: ConnectorInfo }) {
  const [report, setReport] = useState<OutputsReport | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [comparing, setComparing] = useState<string | null>(null)
  const [libraryFiles, setLibraryFiles] = useState<LibraryEntry[]>([])

  const refresh = useCallback(() => {
    setError(null)
    api
      .outputs(connector.name, systemPath)
      .then(setReport)
      .catch((e: unknown) => setError(errText(e)))
  }, [connector.name, systemPath])

  useEffect(refresh, [refresh])

  const startCompare = (outputName: string) => {
    setComparing(outputName)
    api
      .library(connector.name, systemPath)
      .then(setLibraryFiles)
      .catch(() => setLibraryFiles([]))
  }

  return (
    <div className="test-outputs">
      <div className="test-pane-title">
        Outputs <code>{connector.rootPath}</code>
        <button className="flow-refresh" onClick={refresh}>
          Refresh
        </button>
      </div>
      {error && <div className="banner error">{error}</div>}
      {report && !report.exists && (
        <p className="empty">
          The watched directory does not exist yet — the system creates it on its first
          run. Start the system, inject a payload, then refresh.
        </p>
      )}
      {report && report.exists && report.files.length === 0 && (
        <p className="empty">No output files. Inject a payload and refresh after the run.</p>
      )}
      {report && (
        <div className="test-scanned">scanned {new Date(report.scannedAt).toLocaleTimeString()}</div>
      )}
      <ul className="test-filelist">
        {(report?.files ?? []).map((f) => (
          <li key={f.name}>
            <span className="test-file static">{f.name}</span>
            <button className="test-file-action" onClick={() => startCompare(f.name)}>
              Compare with…
            </button>
          </li>
        ))}
      </ul>
      {comparing && (
        <CompareView
          systemPath={systemPath}
          connector={connector.name}
          outputName={comparing}
          libraryFiles={libraryFiles}
          onClose={() => setComparing(null)}
        />
      )}
    </div>
  )
}

// CompareView fetches both files' saved content and renders a line diff:
// lines only in the library file, only in the output, and shared context.
// The presentation is deliberately the smallest dependency-free option.
function CompareView({
  systemPath,
  connector,
  outputName,
  libraryFiles,
  onClose,
}: {
  systemPath: string
  connector: string
  outputName: string
  libraryFiles: LibraryEntry[]
  onClose: () => void
}) {
  const [input, setInput] = useState<string | null>(null)
  const [diff, setDiff] = useState<{ left: string[]; right: string[] } | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [truncatedNote, setTruncatedNote] = useState(false)

  useEffect(() => {
    if (!input) {
      setDiff(null)
      return
    }
    let current = true
    Promise.all([
      api.libraryFile(connector, systemPath, input),
      api.outputContent(connector, systemPath, outputName),
    ])
      .then(([lib, out]) => {
        if (!current) return
        setTruncatedNote(!!lib.truncated || !!out.truncated)
        setDiff({ left: lib.content.split('\n'), right: out.content.split('\n') })
      })
      .catch((e: unknown) => {
        if (current) setError(errText(e))
      })
    return () => {
      current = false
    }
  }, [input, connector, systemPath, outputName])

  return (
    <div className="test-compare">
      <div className="test-editor-head">
        <span className="test-editor-name">compare {outputName}</span>
        <button className="flow-refresh" onClick={onClose}>
          Close
        </button>
      </div>
      <select value={input ?? ''} onChange={(e) => setInput(e.target.value || null)} aria-label="Compare with library file">
        <option value="">Compare with…</option>
        {libraryFiles.map((f) => (
          <option key={f.name} value={f.name}>
            {f.name}
          </option>
        ))}
      </select>
      {error && <div className="banner error">{error}</div>}
      {truncatedNote && (
        <div className="banner test-notice">One side exceeds the read cap; the compare shows truncated content.</div>
      )}
      {diff && <LineDiff left={diff.left} right={diff.right} leftLabel={input ?? ''} rightLabel={outputName} />}
    </div>
  )
}

// LineDiff is a minimal LCS-based line diff. Test payloads are small; a
// full Myers implementation would be machinery without a user.
function LineDiff({
  left,
  right,
  leftLabel,
  rightLabel,
}: {
  left: string[]
  right: string[]
  leftLabel: string
  rightLabel: string
}) {
  const rows = useMemo(() => diffLines(left, right), [left, right])
  return (
    <div className="test-diff">
      <div className="test-diff-head">
        <span>{leftLabel}</span>
        <span>{rightLabel}</span>
      </div>
      <pre>
        {rows.map((r, i) => (
          <div key={i} className={`test-diff-line ${r.kind}`}>
            {r.kind === 'same' ? '  ' : r.kind === 'left' ? '- ' : '+ '}
            {r.text}
          </div>
        ))}
      </pre>
    </div>
  )
}

interface DiffRow {
  kind: 'same' | 'left' | 'right'
  text: string
}

// diffLines computes a longest-common-subsequence alignment of two line
// arrays. O(n·m) in lines — fine for payload-sized files, and the read cap
// bounds both sides.
function diffLines(left: string[], right: string[]): DiffRow[] {
  const n = left.length
  const m = right.length
  const dp: number[][] = Array.from({ length: n + 1 }, () => new Array<number>(m + 1).fill(0))
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      dp[i][j] = left[i] === right[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1])
    }
  }
  const rows: DiffRow[] = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (left[i] === right[j]) {
      rows.push({ kind: 'same', text: left[i] })
      i++
      j++
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      rows.push({ kind: 'left', text: left[i] })
      i++
    } else {
      rows.push({ kind: 'right', text: right[j] })
      j++
    }
  }
  while (i < n) rows.push({ kind: 'left', text: left[i++] })
  while (j < m) rows.push({ kind: 'right', text: right[j++] })
  return rows
}

function errText(e: unknown): string {
  return e instanceof Error ? e.message : String(e)
}

